using System.ComponentModel.DataAnnotations;
namespace WanderXServer.BusinessObject;
public sealed class PhoneVerification { [Key] public Guid Id { get; set; }=Guid.NewGuid(); public Guid UserId { get; set; } [Required,StringLength(20)] public string PhoneNumber { get; set; }=string.Empty; [Required,StringLength(128)] public string OtpHash { get; set; }=string.Empty; public DateTime ExpiresAt { get; set; } public int AttemptCount { get; set; } public int MaxAttempts { get; set; }=5; public int SentCount { get; set; }=1; public DateTime LastSentAt { get; set; }=DateTime.UtcNow; [Required,StringLength(20)] public string Status { get; set; }="Pending"; [StringLength(120)] public string? ProviderMessageId { get; set; } public DateTime CreatedAt { get; set; }=DateTime.UtcNow; public DateTime? VerifiedAt { get; set; } }